using SyWater.Places.Application.Ports.Out;namespace SyWater.Places.Infrastructure.Devices;/// <summary>/// Used while ms-devices is not deployed ("Services:DevicesBaseUrl" is empty)./// Without device-service no device can be linked to a place, so "no device" is the truth./// As soon as ms-devices runs, set the URL and <see cref="HttpDeviceLinkChecker"/> is used instead./// </summary>public sealed class DeviceServiceNotDeployedLinkChecker : IDeviceLinkChecker{    public Task<bool> HasActiveDeviceAsync(Guid placeId, CancellationToken ct) => Task.FromResult(false);}